    private static T Field<T>(FoundationApp app, string name) { return (T)typeof(FoundationApp).GetField(name, BindingFlags.Instance | BindingFlags.NonPublic).GetValue(app); } // Inspect effects on the real private application state.
    private static void Render(FoundationApp app, string click = "", UnityEngine.Event input = null) // Run one actual OnGUI pass with an explicit requested button or map event.
